export const scripts: string[] = ["\n    function calculatePlan() {\n      const status = document.getElementById('pregStatus').value;\n      const coverage = document.querySelector('input[name=\"coverage\"]:checked').value;\n      const waitingEl = document.getElementById('resultWaiting');\n      const planNameEl = document.getElementById('resultPlanName');\n      const adviceEl = document.getElementById('resultAdvice');\n      const waLink = document.getElementById('resultWaLink');\n\n      let planName = \"Star Women Care Comprehensive\";\n      let waiting = \"9-12 Months Accelerated\";\n      let advice = `Optimal fit for normal (\u20b950k) and C-section (up to \u20b9${parseInt(coverage).toLocaleString('en-IN')}) with immediate Day-1 newborn complications and vaccination allowances.`;\n\n      if (status === 'expecting_early') {\n        planName = \"Newborn Day-1 Floater + Group Cover Strategy\";\n        waiting = \"Immediate Newborn Cover\";\n        advice = \"Since pregnancy has already commenced, retail delivery claims are locked under waiting. We structure a Day-1 baby floater that protects against NICU, congenital conditions, and pediatric care right upon birth.\";\n      } else if (status === 'newborn') {\n        planName = \"Immediate Child Protection Plan (0-90 Days)\";\n        waiting = \"Zero Waiting for Illnesses\";\n        advice = \"Immediate floater addition for your newborn baby in Chennai covering hospitalization, emergency surgery, infections, and scheduled immunization reimbursement.\";\n      } else {\n        if (coverage === \"150000\") {\n          planName = \"Star Women Care Deluxe (Unlimited Room Rent)\";\n          waiting = \"12-24 Months\";\n          advice = \"Single private luxury suite covered at Apollo Cradle, Cloudnine, and Rainbow with \u20b91.5L+ Caesarean allowance and complete infant incubator protection.\";\n        }\n      }\n\n      waitingEl.textContent = waiting;\n      planNameEl.textContent = planName;\n      adviceEl.textContent = advice;\n      waLink.href = `https://wa.me/916374423164?text=Hello%20Deeksha,%20I%20used%20the%20Maternity%20Calculator%20for%20${encodeURIComponent(planName)}%20(${encodeURIComponent(status)})`;\n    }\n  "];
